def normalize_timedelta(timedelta):
    """
    Given a string like "1w" or "-5d", convert it to an integer in milliseconds.
    Integers without a suffix are interpreted as seconds.
    Note: not related to the datetime timedelta class.
    """
    suffix_multipliers = {'s': 1000, 'm': 1000*60, 'h': 1000*60*60, 'd': 1000*60*60*24, 'w': 1000*60*60*24*7,
                          'M': 1000*60*60*24*30, 'y': 1000*60*60*24*365}
    if isinstance(timedelta, str) and timedelta[-1:] in suffix_multipliers:
        return int(timedelta[:-1]) * suffix_multipliers[timedelta[-1:]]
    try:
        return int(timedelta) * 1000
    except ValueError as e:
        t, suffix = timedelta[:-1], timedelta[-1:]
        if suffix not in suffix_multipliers:
            raise ValueError()
        return int(t) * suffix_multipliers[suffix]

def _load_versions_manifest():
    """Load versions.json manifest."""
    manifest_path = path.join(path.dirname(dxpy.__file__), 'nextflow', 'versions.json')
    import copy
    cache = globals().setdefault("_versions_manifest_cache", {})
    if manifest_path in cache:
        return copy.deepcopy(cache[manifest_path])
    try:
        with open(manifest_path, 'r') as f:
            manifest = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise dxpy.exceptions.DXCLIError(
            f"Failed to load Nextflow versions manifest at {manifest_path}: {e}")
    if "default" not in manifest or "versions" not in manifest:
        raise dxpy.exceptions.DXCLIError(
            "Malformed Nextflow versions manifest: missing 'default' or 'versions' key")
    required_keys = {"status", "nextflow_assets", "nextaur_assets", "awscli_assets", "cache_digest_type"}
    valid_digest_types = {"config", "manifest"}
    for ver, cfg in manifest["versions"].items():
        missing = required_keys - set(cfg.keys())
        if missing:
            raise dxpy.exceptions.DXCLIError(
                f"Malformed version entry '{ver}': missing keys {sorted(missing)}")
        digest_type = cfg.get("cache_digest_type")
        if digest_type not in valid_digest_types:
            raise dxpy.exceptions.DXCLIError(
                f"Invalid cache_digest_type '{digest_type}' in version '{ver}'; expected one of {sorted(valid_digest_types)}")
    cache[manifest_path] = copy.deepcopy(manifest)
    return manifest

