def translate(pat):
    """
    A copy of fnmatch.translate that replaces with [^\/] instead of . to match path globs.
    """

    i, n = 0, len(pat)
    res = []
    while i < n:
        c = pat[i]
        i = i+1
        if c == '*':
            res.append('[^\/]*')
        elif c == '?':
            res.append('[^\/].')
        elif c == '[':
            j = i
            if j < n and pat[j] == '!':
                j = j+1
            if j < n and pat[j] == ']':
                j = j+1
            while j < n and pat[j] != ']':
                j = j+1
            if j >= n:
                res.append('\\[')
            else:
                stuff = pat[i:j].replace('\\','\\\\')
                i = j+1
                if stuff[0] == '!':
                    stuff = '^' + stuff[1:]
                elif stuff[0] == '^':
                    stuff = '\\' + stuff
                res.append('[%s]' % (stuff,))
        else:
            res.append(re.escape(c))
    return '(?ms)' + ''.join(res) + '\Z'

